export function distance(a: SwarmPoint, b: SwarmPoint): number {
  const dx = a.x - b.x, dy = a.y - b.y, dz = a.z - b.z;
  return isqrt(dx * dx + dy * dy + dz * dz);
}
export const horizontalDistance = (a: SwarmPoint, b: SwarmPoint): number => isqrt((a.x - b.x) * (a.x - b.x) + (a.z - b.z) * (a.z - b.z));
export const pointAt = (samples: Int32Array, i: number): SwarmPoint => ({ x: samples[3 * i]!, y: samples[3 * i + 1]!, z: samples[3 * i + 2]! });

/** Nearest table direction by monotone first-quadrant cross products; ties choose the lower index. */
export function directionOf(dx: number, dz: number): number {
  if (dx === 0 && dz === 0) return 0;
  const x = Math.abs(dx), z = Math.abs(dz);
  let lo = 0, hi = 1024;
  while (hi - lo > 1) {
    const mid = (lo + hi) >>> 1;
    if (DIRECTIONS[2 * mid]! * z > DIRECTIONS[2 * mid + 1]! * x) lo = mid;
    else hi = mid;
  }
  const crossLo = Math.abs(DIRECTIONS[2 * lo]! * z - DIRECTIONS[2 * lo + 1]! * x);
  const crossHi = Math.abs(DIRECTIONS[2 * hi]! * z - DIRECTIONS[2 * hi + 1]! * x);
  const a = crossLo <= crossHi ? lo : hi;
  return (dx >= 0 ? (dz >= 0 ? a : 4096 - a) : (dz >= 0 ? 2048 - a : 2048 + a)) & 4095;
}

export function inset(value: number, min: number, max: number, margin: number): number {
  return max - min < 2 * margin ? mulDivSym(min + max, 1, 2) : clamp(value, min + margin, max - margin);
}
export function inBounds(p: SwarmPoint, bounds: SwarmBounds, margin = SWARM.geometry.marginMm): boolean {
  const minX = inset(bounds.minXMm, bounds.minXMm, bounds.maxXMm, margin);
  const maxX = inset(bounds.maxXMm, bounds.minXMm, bounds.maxXMm, margin);
  const minZ = inset(bounds.minZMm, bounds.minZMm, bounds.maxZMm, margin);
  const maxZ = inset(bounds.maxZMm, bounds.minZMm, bounds.maxZMm, margin);
  return p.x >= minX && p.x <= maxX && p.z >= minZ && p.z <= maxZ;
}

/** Radius of each 1 m/1 m horizontal triple; every member must be outside the 8 m exclusion. */
export function minimumRadiusMm(base: Int32Array, pearl: SwarmPoint): number {
  let min = Number.MAX_SAFE_INTEGER;
  const stride = SWARM.geometry.radiusProbeMm / SWARM.geometry.stepMm;
  const exclusion = SWARM.geometry.radiusExclusionMm;
  for (let i = stride; i + stride < base.length / 3; i += 1) {
    const a = pointAt(base, i - stride), b = pointAt(base, i), c = pointAt(base, i + stride);
    if (horizontalDistance(a, pearl) <= exclusion || horizontalDistance(b, pearl) <= exclusion || horizontalDistance(c, pearl) <= exclusion) continue;
    const cross = Math.abs((b.x - a.x) * (c.z - a.z) - (b.z - a.z) * (c.x - a.x));
    if (cross === 0) continue;
    const ab = horizontalDistance(a, b), bc = horizontalDistance(b, c), ac = horizontalDistance(a, c);
    min = Math.min(min, Math.floor(ab * bc * ac / (2 * cross)));
  }
  return min;
}

function flatten(points: readonly SwarmPoint[]): Int32Array {
  const out = new Int32Array(points.length * 3);
  for (let i = 0; i < points.length; i += 1) { const p = points[i]!; out.set([p.x, p.y, p.z], i * 3); }
  return out;
}

/** Bake the polyline at 250 mm arc intervals and keep the exact endpoint. */
function bake(points: readonly SwarmPoint[]): { base: Int32Array; arc: number[]; length: number } {
  const out: SwarmPoint[] = [points[0]!];
  const arc = [0];
  // Sub-millimetre arc accumulation prevents floor error at the 62 mm spline subdivisions.
  const arcUnits = 60;
  let walked = 0, next = SWARM.geometry.stepMm * arcUnits;
  for (let i = 1; i < points.length; i += 1) {
    const a = points[i - 1]!, b = points[i]!;
    const dx = (b.x - a.x) * arcUnits, dy = (b.y - a.y) * arcUnits, dz = (b.z - a.z) * arcUnits;
    const len = isqrt(dx * dx + dy * dy + dz * dz);
    if (len === 0) continue;
    while (next <= walked + len) {
      const f = next - walked;
      out.push({ x: a.x + mulDivSym(b.x - a.x, f, len), y: a.y + mulDivSym(b.y - a.y, f, len), z: a.z + mulDivSym(b.z - a.z, f, len) });
      arc.push(Math.floor(next / arcUnits)); next += SWARM.geometry.stepMm * arcUnits;
    }
    walked += len;
  }
  const end = points[points.length - 1]!;
  if (distance(out[out.length - 1]!, end) !== 0) { out.push(end); arc.push(Math.ceil(walked / arcUnits)); }
  arc[arc.length - 1] = Math.ceil(walked / arcUnits);
  return { base: flatten(out), arc, length: Math.ceil(walked / arcUnits) };
}

/** Clamped quadratic B-spline, four integer subdivisions per steering interval. */
function smooth(points: readonly SwarmPoint[]): SwarmPoint[] {
  const out: SwarmPoint[] = [];
  for (let k = 0; k < points.length; k += 1) {
    const a = points[Math.max(0, k - 1)]!, b = points[k]!, c = points[Math.min(points.length - 1, k + 1)]!;
    for (let f = 0; f < 4; f += 1) {
      const wa = (4 - f) * (4 - f), wb = 16 + 8 * f - 2 * f * f, wc = f * f;
      out.push({ x: mulDivSym(a.x * wa + b.x * wb + c.x * wc, 1, 32), y: mulDivSym(a.y * wa + b.y * wb + c.y * wc, 1, 32), z: mulDivSym(a.z * wa + b.z * wb + c.z * wc, 1, 32) });
    }
  }
  out.push(points[points.length - 1]!);
  return out;
}

function valid(base: Int32Array, length: number, pearl: SwarmPoint, bounds: SwarmBounds): boolean {
  if (length > SWARM.geometry.maxLengthMm || base.length > 3 * SWARM.geometry.maxSamples) return false;
  for (let i = 0; i < base.length / 3; i += 1) if (!inBounds(pointAt(base, i), bounds)) return false;
  // A terminal dive may curve into P, but may not orbit away from it.
  let remaining = 0;
  for (let i = base.length / 3 - 2; i >= 0; i -= 1) {
    const a = pointAt(base, i), b = pointAt(base, i + 1);
    remaining += distance(a, b);
    if (remaining > SWARM.geometry.diveMm) break;
    if (horizontalDistance(b, pearl) > horizontalDistance(a, pearl) + 1) return false;
  }
  return minimumRadiusMm(base, pearl) >= SWARM.geometry.radiusFloorMm;
}

/** Fixed spatial helix: amplitude is solely a function of s, never body station or tick. */
export function helix(base: Int32Array, arc: readonly number[], dragon: number): Int32Array {
  const out = new Int32Array(base.length);
  const h = SWARM.helix, length = arc[arc.length - 1]!;
  for (let i = 0; i < arc.length; i += 1) {
    const p = pointAt(base, i), a = pointAt(base, Math.max(0, i - 1)), b = pointAt(base, Math.min(arc.length - 1, i + 1));
    const dx = b.x - a.x, dz = b.z - a.z, norm = isqrt(dx * dx + dz * dz);
    const amplitude = Math.min(1000, Math.floor(arc[i]! * 1000 / h.riseMm), Math.floor((length - arc[i]!) * 1000 / h.fadeMm));
    const phase = (Math.floor(arc[i]! * 4096 / h.wavelengthMm) + Math.floor(dragon * 4096 / SWARM.dragons)) & 4095;
    const lateral = mulDivSym(mulDiv(h.horizontalMm, amplitude, 1000), SIN[phase]!, TABLE_SCALE);
    out[3 * i] = p.x + (norm === 0 ? 0 : mulDivSym(-dz, lateral, norm));
    out[3 * i + 1] = p.y + mulDivSym(mulDiv(h.verticalMm, amplitude, 1000), SIN[(phase + 1024) & 4095]!, TABLE_SCALE);
    out[3 * i + 2] = p.z + (norm === 0 ? 0 : mulDivSym(dx, lateral, norm));
  }
  return out;
}

/** Fly the horizontal heading; then interpolate reachable waypoint heights at slope <= 1:2. */
export function steerRoute(origin: SwarmPoint, targets: readonly SwarmPoint[], pearl: SwarmPoint, bounds: SwarmBounds, dragon: number): SwarmPath | null {
  const goals = [...targets, pearl];
  const raw: SwarmPoint[] = [origin];
  const anchors: { index: number; y: number }[] = [{ index: 0, y: origin.y }];
  let x = origin.x, z = origin.z, heading = directionOf(goals[0]!.x - x, goals[0]!.z - z), target = 0, walked = 0;
  while (target < goals.length && walked <= SWARM.geometry.maxLengthMm) {
    const goal = goals[target]!, dx = goal.x - x, dz = goal.z - z;
    const d = isqrt(dx * dx + dz * dz), last = target === goals.length - 1;
    if ((!last && (d < 3000 || (d < 8000 && dx * DIRECTIONS[heading * 2]! + dz * DIRECTIONS[heading * 2 + 1]! < 0))) || (last && d <= SWARM.geometry.stepMm)) {
      if (last && d > 0) { raw.push({ x: goal.x, y: origin.y, z: goal.z }); walked += d; }
      anchors.push({ index: raw.length - 1, y: goal.y }); target += 1;
      continue;
    }
    let turn: number = SWARM.geometry.maxTurn;
    if (last && d < SWARM.geometry.diveMm) {
      const r = Math.max(SWARM.geometry.diveMinRadiusMm, Math.min(SWARM.geometry.turnRadiusMm, Math.floor(d / 2)));
      const t = clamp(mulDiv(d - SWARM.geometry.diveInnerMm, 1000, SWARM.geometry.diveMm - SWARM.geometry.diveInnerMm), 0, 1000);
      const smoothPm = mulDiv(t * t, 3000 - 2 * t, 1_000_000);
      const radius = r + mulDiv(SWARM.geometry.turnRadiusMm - r, smoothPm, 1000);
      turn = Math.max(turn, Math.floor(SWARM.geometry.stepMm * 4096 * 1000 / (6283 * radius)));
    }
    const desired = directionOf(dx, dz), delta = ((desired - heading + 6144) & 4095) - 2048;
    heading = (heading + clamp(delta, -turn, turn) + 4096) & 4095;
    const nx = x + mulDivSym(DIRECTIONS[heading * 2]!, SWARM.geometry.stepMm, TABLE_SCALE);
    const nz = z + mulDivSym(DIRECTIONS[heading * 2 + 1]!, SWARM.geometry.stepMm, TABLE_SCALE);
    walked += isqrt((nx - x) * (nx - x) + (nz - z) * (nz - z));
    x = nx; z = nz; raw.push({ x, y: origin.y, z });
    if (!inBounds(raw[raw.length - 1]!, bounds)) return null;
  }
  if (target !== goals.length) return null;
  for (let k = 1; k < anchors.length; k += 1) {
    const a = anchors[k - 1]!, b = anchors[k]!;
    let length = 0;
    for (let i = a.index + 1; i <= b.index; i += 1) length += horizontalDistance(raw[i - 1]!, raw[i]!);
    if (Math.abs(b.y - a.y) * SWARM.geometry.maxSlopeDenominator > length) return null;
    let s = 0;
    for (let i = a.index; i <= b.index; i += 1) {
      if (i > a.index) s += horizontalDistance(raw[i - 1]!, raw[i]!);
      raw[i] = { ...raw[i]!, y: a.y + (length === 0 ? 0 : mulDivSym(b.y - a.y, s, length)) };
    }
  }
  let baked = bake(smooth(raw));
  let smoothed = true;
  if (!valid(baked.base, baked.length, pearl, bounds)) { baked = bake(raw); smoothed = false; }
  if (!valid(baked.base, baked.length, pearl, bounds)) return null;
  const samples = helix(baked.base, baked.arc, dragon);
  for (let i = 1; i < baked.arc.length; i += 1) if (distance(pointAt(samples, i - 1), pointAt(samples, i)) > 600) return null;
  return { base: baked.base, samples, arc: baked.arc, lengthMm: baked.length, smoothed };
}

/** Round-3 fallback: straight C -> P, same 16 m/s; no orbit or invented target. */
export function straightRoute(origin: SwarmPoint, pearl: SwarmPoint, dragon: number): SwarmPath {
  const baked = bake([origin, pearl]);
  if (baked.length > SWARM.geometry.maxLengthMm || baked.arc.length > SWARM.geometry.maxSamples) throw new Error("swarm: fallback exceeds path cap");
  return { base: baked.base, samples: helix(baked.base, baked.arc, dragon), arc: baked.arc, lengthMm: baked.length, smoothed: false };
}
